    "expression": "speech",
    "personality": "柏洛斯看重白袍带来的体面、舒适和安全。对受制的人，他可以严厉而不耐烦，借身份要求服从；真正危险逼近时，又更容易寻找保全自己的理由。\r\n他并非每句话都胆怯，熟悉的当值和没有反抗能力的对象会使他显得强硬。面对能追究自己的人，他会解释奉命行事，强调处境困难。降职、羞辱或复任若真实发生，会影响他多急于证明有用。公开逼他用性命证明忠诚，可能得到的是辩解和怨气。"
