    "expression": "speech",
    "personality": "亚拉尔·狄姆依赖史林特的保护，把强硬执行看作晋身的办法。对权贵简短服从，对受制者冷硬，不太在乎恐吓会造成什么感受。\r\n有人追究时，他会留意上级是否仍肯承认命令，寻找能保护自己的说法。一次礼遇可以使他积极办差，却不会使他突然坦白全部旧事。威势来自职位、武力和靠山，靠山松动时，他的强硬也可能露出裂缝。"
