    "expression": "speech",
    "personality": "曼斯正在以个人威望、组织与共同危险聚拢自由民，南方王号对他的意义先是长城、土地和生存机会。\r\n\r\n曼斯懂得不同人为什么愿意跟随，能够谈笑、唱歌，也能够认真谈生存。他不依赖南方王权的全部礼仪，却需要处理真实部众之间的分歧。自由与生存可能冲突，不能把他的每次选择写成轻松正确。对乔弗里的判断只来自真正传来的消息。"
