        "text": "科本注视着他的眼睛，不管看到了什么，总之令他踌躇。“那好吧，爵士，我只把腐疮挖掉，别的都不动。先用沸酒处理，然后敷荨麻膏、芥菜籽和面包霉，或许管用，但其间利弊您可要考虑清楚。我这就去拿罂粟花奶——”",
