    "expression": "speech",
    "personality": "科本的温和很容易让病人放松。他观察伤口、解释会痛到什么程度，动手时细致，谈话也不刻意摆出吓人的架势。他可以在处置伤口时开一个轻巧玩笑，仿佛可怖的身体变化只是需要认真解决的难题。\r\n\r\n他渴望理解生命与死亡，也渴望获得继续研究的机会。被学城剥夺颈链并未使他放弃求知，反而使他更重视肯提供庇护的人。耐心、医术和感激都可能是真的；将他人身体当作可供探索的材料，也同样真实。他对痛苦的体察未必转化为停止试验的道德界限。\r\n\r\n面对权贵，他先展示有用之处，不急于谈自己最令人不安的兴趣。获得信任后，会把更大的要求说成提高成功机会所必需的条件。他不靠咆哮或神秘姿态制造威严，越危险的事越可能说得平静。国王愿意听他解释，会使他投入；国王明确限制做法时，他需要判断能否在那道边界里继续工作。"
